#include "engine/world_road_traffic_core.h"
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iomanip>
#include <filesystem>
#include <sstream>
#include <string>
#include <limits>
#include <unistd.h>
using namespace world_road_traffic_core;
static unsigned checks=0;
static void need(bool ok,const char *why){++checks;if(!ok){std::fprintf(stderr,"FAIL %s at%u\n",why,checks);std::exit(1);}}
static bool ground(double,double,double y,double &out,const void*){out=y;return std::isfinite(y);}
static bool clear(double,double,double,double,double,double,double,const void*){return true;}
static Core make(const WorldRoadTrafficConfig &cfg){Core c;need(c.route.build(cfg),"actual widened config builds");c.profiles={{{.35,.49,.54,1.84,1,1.02},{.35,.8,.44,1.86,1,1.08},{.35,.5,.55,1.84,1,1.14},{.35,.51,.59,1.84,1,1.20},{.70,2.71,1.38,3.17,1.259987,1.18},{.90,.91,3.09,2.42,.9811,.88}}};need(c.validate({ground,clear,nullptr}),"actual source-fitted profiles validate lanes and turnarounds");return c;}
static void config(const char *file,WorldRoadTrafficConfig &cfg){char why[256];need(world_road_traffic_config_load(file,cfg,why,sizeof why),"production parser loads actual candidate file");need(cfg.lane_offset==1.65&&cfg.road_half_width==2.75,"actual widened lane/road width");need(WORLD_ROAD_TRAFFIC_ACTORS==31,"all31 actors retained");std::ifstream in(file);std::ostringstream text;text<<in.rdbuf();const auto source=text.str();const auto at=source.find("lanes 1.65 2.75");need(at!=std::string::npos,"exact candidate lane record");const auto temp=std::filesystem::temp_directory_path()/("valwood-widened-traffic-"+std::to_string(getpid())+".settings");for(const char *lane:{"0.70","1.30","1.50","1.65","1.70","0.6999999","1.7000001","-1","nan","inf","-inf","1e309","1e100"}){auto s=source;s.replace(at,std::string("lanes 1.65 2.75").size(),std::string("lanes ")+lane+" 2.75");{std::ofstream out(temp);out<<s;}auto parsed=cfg;bool actual=world_road_traffic_config_load(temp.c_str(),parsed,why,sizeof why);const bool expected=std::string(lane)=="0.70"||std::string(lane)=="1.30"||std::string(lane)=="1.50"||std::string(lane)=="1.65"||std::string(lane)=="1.70";need(actual==expected,"production file parser boundary/NaN/overflow policy");if(!actual)need(parsed.lane_offset==cfg.lane_offset&&parsed.points[0].x==cfg.points[0].x,"invalid parse preserves prior valid config");}std::filesystem::remove(temp);for(double invalid:{std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::infinity(),-std::numeric_limits<double>::infinity(),1e100}){auto c=cfg;c.lane_offset=invalid;Route r;need(!r.build(c),"direct core invalid lane rejected");}}
static void envelopes(const WorldRoadTrafficConfig &cfg){auto c=make(cfg);c.enabled=c.initialized=true;for(auto &a:c.actors)a.view.active=false;auto &v=c.actors[0].view;v.active=true;double minimum[6]={9,9,9,9,9,9};unsigned poses=0,center_pairs=0;for(unsigned bank=0;bank<6;++bank){v.kind=bank<4?WorldRoadTrafficKind::Walker:bank==4?WorldRoadTrafficKind::Rider:WorldRoadTrafficKind::Pullcart;v.appearance=bank<4?bank:0;const auto &f=c.profiles[bank];const double arc=pi*cfg.lane_offset;for(double s=0;s<c.route.cycle;s+=.25){auto p=c.route.sample(s);p.y+=.015;v.x=p.x;v.y=p.y;v.z=p.z;v.yaw=std::atan2(p.dx,p.dz);const auto cap=capsule(p,f);double st=s<=c.route.length?s:s<c.route.length+arc?c.route.length:s<=2*c.route.length+arc?2*c.route.length+arc-s:0;for(double d=-5;d<=5;d+=.1){auto a=c.route.center(st+d);const double free=std::sqrt(point_segment(a.x,a.z,cap.ax,cap.az,cap.bx,cap.bz))-f.radius;minimum[bank]=std::min(minimum[bank],free);need(!c.blocks(a.x,a.z,a.x,a.z,a.y+.015,1.75,.37),"centerline player clears actual actor envelope including corners/turnarounds");++center_pairs;}const double r=f.radius+2,dx=p.dz*r,dz=-p.dx*r;need(!c.camera_clear(p.x-dx,p.y+f.height*.5,p.z-dz,p.x+dx,p.y+f.height*.5,p.z+dz,.23,.02),"lens sweep detects fitted moving body");need(c.camera_clear(p.x-dx,p.y+f.height+.5,p.z-dz,p.x+dx,p.y+f.height+.5,p.z+dz,.23,.02),"camera above full human/rider/cart remains clear");++poses;}}need(minimum[5]>.46,"cart corner has real player radius plus9cm margin");std::printf("Full widened route: %u source-envelope poses, %u player-center pairs, cart minimumfree%.9fm\n",poses,center_pairs,minimum[5]);}
static void dynamic(const WorldRoadTrafficConfig &cfg){auto c=make(cfg);WorldRoadTrafficFrame f;f.query={ground,clear,nullptr};f.dt=1./23;f.player_x=cfg.camp.x;f.player_z=cfg.camp.z;f.player_feet_y=cfg.camp.y;f.encounter_cleared=true;double walked=0;unsigned snapshots=0;for(unsigned k=0;k<23*180;++k){c.update(f);if(k%23==0){++snapshots;unsigned walkers=0,riders=0,carts=0;for(unsigned i=0;i<31;++i){auto &a=c.actors[i];need(a.view.active&&a.view.id==i,"all dynamic actors retain stable IDs");walkers+=a.view.kind==WorldRoadTrafficKind::Walker;riders+=a.view.kind==WorldRoadTrafficKind::Rider;carts+=a.view.kind==WorldRoadTrafficKind::Pullcart;auto p=c.route.sample(a.station);need(std::hypot(a.view.x-p.x,a.view.z-p.z)<1e-8,"actual dynamic body remains on widened route");auto body=capsule({a.view.x,a.view.y,a.view.z,std::sin(a.view.yaw),std::cos(a.view.yaw)},c.profile(a));for(unsigned j=i+1;j<31;++j){auto &v=c.actors[j].view;auto other=capsule({v.x,v.y,v.z,std::sin(v.yaw),std::cos(v.yaw)},c.profile(c.actors[j]));need(separate(body,other),"dynamic opposing lanes never overlap source envelopes");}}need(walkers==24&&riders==4&&carts==3,"original mixed population retained");}if(k==230){auto before=c.actors;const auto time=c.clock;f.paused=true;for(unsigned j=0;j<23;++j)c.update(f);need(c.clock==time,"pause retains traffic clock");for(unsigned i=0;i<31;++i)need(c.actors[i].station==before[i].station,"pause keeps all widened actors stationary");f.paused=false;}}for(auto &a:c.actors)walked+=a.view.travelled;need(c.initialized&&c.stats.failures==0&&walked>500,"full dynamic crowd advances without failures");std::printf("Dynamic widened route: %u snapshots,31 actors,%.3fm aggregate actual travel\n",snapshots,walked);}
int main(int argc,char**argv){need(argc==2,"actual candidate settings path required");WorldRoadTrafficConfig cfg;config(argv[1],cfg);envelopes(cfg);dynamic(cfg);std::printf("PASS %u widened production config/envelope/dynamic/camera checks\n",checks);}
